-- VibeSchool CPA CA11 | First authored learning unit, non-public release candidate
-- Official section: June 2024 KASNEB CPA syllabus, printed page 1, 1.1–1.5.
-- https://www.kasneb.or.ke/wp-content/uploads/2024/09/CPA-Syllabus-Reviewed-June-2024.pdf
-- CA11 code corroboration: KASNEB April 2026 qualifications booklet, printed page 5.
-- https://www.kasneb.or.ke/sites/default/files/2026-04/QUALIFICATIONS%20BOOKLET.pdf
-- Technical definitions: https://www.ifrs.org/issued-standards/list-of-standards/conceptual-framework/
-- Intentionally STAGE ONLY: no change to courses.status, no published topics,
-- no authority grants, no account writes, no learner enrollment and no approval shortcut.
begin;
do $ca11_preflight$
declare v_count int;
begin
  select count(*) into v_count
  from public.courses c join public.modules m on m.course_id=c.id
  where c.slug='kasneb-cpa' and c.status='coming_soon'
    and c.qualifying_body='KASNEB' and c.qualification_code='CPA'
    and m.slug='ca11' and m.qualification_level='Foundation';
  if v_count<>1 then raise exception 'CA11 source-qualified unpublished paper missing or ambiguous'; end if;
  if exists (select 1 from public.topics t
    join public.modules m on m.id=t.module_id
    join public.courses c on c.id=m.course_id
    where c.slug='kasneb-cpa' and m.slug='ca11' and t.content_status='published'
  ) then raise exception 'CA11 staging may not alter a released topic'; end if;
end $ca11_preflight$;

