-- canonical Academy tables; the checked-in test parses this exact packet.
with packet as (
 select $ca11data${"metadata":{"edition":"VibeSchool Originals · CA11 Foundation Unit 01","release_state":"in_review","scope":"KASNEB CPA Financial Accounting syllabus June 2024 sections 1.1–1.5 only","source_version":"2024-06","sources":[{"url":"https://www.kasneb.or.ke/wp-content/uploads/2024/09/CPA-Syllabus-Reviewed-June-2024.pdf","locator":"printed page 1, Introduction to Accounting subsections 1.1–1.5","role":"examinable topic scope"},{"url":"https://www.kasneb.or.ke/sites/default/files/2026-04/QUALIFICATIONS%20BOOKLET.pdf","locator":"printed page 5, Foundation Level CA11","role":"2026 course and paper identity"},{"url":"https://www.ifrs.org/issued-standards/list-of-standards/conceptual-framework/","locator":"Conceptual Framework overview and elements","role":"technical anchor for financial-statement elements"}],"coverage":["1.1","1.2","1.3","1.4","1.5"],"rights":"Original prose, scenarios and questions; official sources used for scope and technical fact-checking, not copied text","review_status":"Editorial draft; independent qualification/source coverage and full learner-flow QA pending","limits":"Does not certify other CA11 syllabus sections, other CPA papers, or the platform learning journey."},"topics":[{"slug":"why-accounts-matter","title":"Why businesses keep accounts","subtitle":"Purpose, financial reporting and the people who rely on it","sequence_number":1,"concept_tab":[{"title":"Start with a business, not a definition","text":"A customer pays KSh 15,000. A supplier is still owed KSh 8,000. The owner takes KSh 5,000 for personal use. These are three different events. The receipt increases business cash; the unpaid supplier balance is an obligation; the owner's withdrawal reduces what remains invested in the business. The accountant's job is to record each event faithfully and explain what the records reveal."},{"title":"Why cash alone is not enough","text":"Imagine two businesses with KSh 100,000 in their bank accounts. One owes nothing. The other owes suppliers KSh 90,000. A bank statement gives the same cash figure for both, but it cannot tell a lender that their financial positions are equal. Good financial records bring obligations, resources, income and expenses into the picture."},{"title":"What financial accounting does","text":"Financial accounting turns evidence of transactions into records and reports. The work begins with an event supported by documentation, continues through classification and recording, and ends with information that can be understood and checked. Bookkeeping is part of this process; accounting also involves summarising and interpreting the results. The records should describe the business, not what its owner wishes the figures to show."},{"title":"The questions a set of accounts should answer","text":"A statement of financial position helps show resources, obligations and the remaining interest of owners at a particular date. A statement of financial performance helps explain income and expenses over a period. Cash-flow information describes cash received and paid. These reports answer different questions. A profit figure is not a bank balance, and a strong balance sheet does not automatically mean cash is available today."},{"title":"Whose decision is it?","text":"The owner may use figures to monitor results and control spending. A bank considers the ability to repay a loan. A supplier offering credit looks at whether invoices are likely to be paid. Investors and other lenders assess risks and returns. Tax authorities may need records for compliance. General-purpose financial reporting is primarily designed to help existing and potential investors, lenders and other creditors make decisions; management may need additional internal information."},{"title":"An accountant's first habit","text":"Before deciding where an amount belongs, ask four questions: What happened? What evidence supports it? Did the business gain a resource, incur an obligation, earn income or use resources? Who needs to understand the effect? Those questions make the later rules of double entry easier to learn; they also expose errors that neat-looking numbers can conceal."}],"kenya_context_tab":[{"title":"A Kenyan small-business example","text":"A workshop has KSh 60,000 in M-PESA and bank balances combined, repair tools worth KSh 45,000 and a KSh 30,000 supplier bill. Reporting only the cash would ignore both the tools used to earn income and the unpaid obligation. The owner needs all three figures before judging how much can safely be withdrawn."},{"title":"The evidence trail","text":"A receipt, bank transaction record, supplier invoice or signed agreement can help explain a transaction. Keep business and personal spending distinguishable even when the owner runs a one-person enterprise. The precise source document and its treatment will be explored in the next CA11 unit."}],"common_errors_tab":[{"title":"Cash is not profit","text":"A loan increases cash but also creates an obligation. Money received does not necessarily mean income has been earned. Ask where the cash came from before treating it as profit."},{"title":"A business is not its owner","text":"For accounting records, the business's transactions must be distinguishable from personal transactions. An owner's personal withdrawal is normally drawings, not a business operating expense."}],"clinical_tip_tab":[{"title":"Try the lender's question","text":"A trader has KSh 80,000 in cash and KSh 70,000 of unpaid supplier invoices. Explain, in two sentences, why a lender would need both figures. A sound answer identifies the cash as a resource and the unpaid invoices as obligations, without assuming the trader has only KSh 10,000 of net assets: other resources or debts may exist."}]},{"slug":"five-elements-of-financial-statements","title":"Five elements, five different jobs","subtitle":"Assets, liabilities, equity, income and expenses","sequence_number":2,"concept_tab":[{"title":"First separate position from performance","text":"Some accounting figures describe the business at a date; others explain what changed during a period. Assets, liabilities and equity belong to financial position. Income and expenses explain financial performance and, in many cases, change equity. Mixing those two purposes leads to weak explanations and incorrect calculations."},{"title":"Assets: resources the business controls","text":"An asset is a present economic resource controlled by an entity because of past events. In ordinary business language, it is something the business controls that has potential economic benefit. Examples include cash, stock held for sale, a trade receivable and equipment used to provide services. Ownership documents are relevant, but control—not merely holding a physical item—is central to the definition."},{"title":"Liabilities: obligations already created","text":"A liability is a present obligation to transfer an economic resource arising from past events. An unpaid supplier invoice is a common example. So is money already borrowed and not yet repaid. A plan to buy a delivery van next month is not automatically a liability today: wanting to spend money is different from having a present obligation."},{"title":"Equity: the remaining interest","text":"Equity is what remains of the recognised assets after deducting recognised liabilities. For a simple sole-trader example, think of it as the owner's residual interest. It is not the same as the cash balance. A business might have equipment and inventory, owe suppliers and still have substantial equity despite little money in the bank."},{"title":"Income and expenses","text":"Income generally reflects increases in assets or decreases in liabilities that increase equity, apart from contributions made by owners. Expenses generally reduce equity through decreases in assets or increases in liabilities, apart from distributions to owners. Revenue from completed services is a familiar type of income. Rent used during the period is a familiar expense. Capital introduced and drawings are owner transactions; neither should be disguised as sales or operating costs."},{"title":"Worked classification: calculate, then explain","text":"At 30 June, a trader has KSh 65,000 in the bank, KSh 14,000 owed by customers and equipment worth KSh 21,000. The trader owes a supplier KSh 25,000 and has an unpaid electricity bill of KSh 5,000 relating to the period. Step 1: assets are 65,000 + 14,000 + 21,000 = KSh 100,000. Step 2: liabilities are 25,000 + 5,000 = KSh 30,000. Step 3: residual equity is 100,000 − 30,000 = KSh 70,000. Check that 100,000 = 30,000 + 70,000. The unpaid bill is an accrued expense and an obligation; the customer balance is a receivable, not cash."}],"kenya_context_tab":[{"title":"From an invoice to a financial statement","text":"A stationery seller supplies notebooks to a local office on credit for KSh 12,000. The seller has a claim to payment even though cash has not arrived. That claim is a trade receivable. The seller must not confuse money owed by customers with money already received. A separate later lesson will address the full entries and revenue-recognition conditions."},{"title":"Business labels need evidence","text":"A spare phone kept for personal use is not automatically a business asset. A printer paid for from a business account may be one if controlled for business operations. Record the commercial substance and the supporting evidence, not simply the label on a receipt."}],"common_errors_tab":[{"title":"Receivable versus payable","text":"A receivable means another party owes the business. A payable means the business owes another party. Reverse them and both the balance sheet and the business decision become unreliable."},{"title":"Planned spending versus an obligation","text":"Budgeting for next month's advertising does not by itself create a present liability. An obligation is assessed from what has already happened and the terms involved."},{"title":"Owner's cash withdrawal is not an expense","text":"When a sole trader withdraws business cash for personal use, cash and owner's equity fall. Recording the withdrawal as an operating expense would misstate performance."}],"clinical_tip_tab":[{"title":"Check the words before using the formula","text":"When a question says 'owed to us', look for a receivable (asset). When it says 'we owe', consider a payable (liability). Then ask whether the amount relates to business activity and whether the obligation or right exists at the reporting date."}]},{"slug":"the-equation-in-action","title":"Make the accounting equation work","subtitle":"Follow six transactions and prove each balance","sequence_number":3,"concept_tab":[{"title":"The relationship that must hold","text":"Assets = Liabilities + Equity. It can also be written as Equity = Assets − Liabilities. These are two forms of one relationship: resources are financed through obligations to others and the residual interest of owners. The equation is not a shortcut for recognising assets or liabilities; the definitions and evidence still matter."},{"title":"1. The owner starts trading","text":"An owner pays KSh 120,000 into a new business bank account. Assets: cash KSh 120,000. Liabilities: KSh 0. Equity: KSh 120,000. Check: 120,000 = 0 + 120,000. The contribution introduces capital; it is not sales income."},{"title":"2. The business buys a laptop for cash","text":"A laptop costing KSh 40,000 is purchased for business use. Cash becomes KSh 80,000 and equipment becomes KSh 40,000. Total assets are still KSh 120,000; liabilities and equity are unchanged. One asset has been exchanged for another. Buying a usable long-term asset is not the same event as paying an ordinary running expense."},{"title":"3. Stock arrives before payment","text":"The business buys inventory worth KSh 30,000 on supplier credit. Cash stays at KSh 80,000, equipment KSh 40,000 and inventory KSh 30,000. Assets now total KSh 150,000. Trade payables are KSh 30,000 and equity remains KSh 120,000. Check: 150,000 = 30,000 + 120,000. Credit has increased both resources and obligations."},{"title":"4. Part of the supplier balance is paid","text":"The business pays the supplier KSh 10,000. Cash falls to KSh 70,000; equipment and inventory remain KSh 40,000 and KSh 30,000. Assets total KSh 140,000. The amount still owed is KSh 20,000. Equity is unchanged at KSh 120,000. Check: 140,000 = 20,000 + 120,000. Payment reduces both the asset and the liability."},{"title":"5. The business earns service fees in cash","text":"A completed service earns KSh 15,000 received immediately. Cash rises to KSh 85,000. With equipment of KSh 40,000 and inventory of KSh 30,000, assets total KSh 155,000. Liabilities remain KSh 20,000. Equity rises to KSh 135,000 because earned income increases the residual interest. Check: 155,000 = 20,000 + 135,000. This example assumes no related expense arises from providing the service."},{"title":"6. The owner withdraws money","text":"The owner takes KSh 5,000 in cash for personal use. Cash falls to KSh 80,000; equipment and inventory remain KSh 40,000 and KSh 30,000. Assets are KSh 150,000; liabilities KSh 20,000; equity KSh 130,000. Check: 150,000 = 20,000 + 130,000. Drawings reduce equity, but are not an operating expense of the business."},{"title":"The final check","text":"The original contribution of KSh 120,000 plus KSh 15,000 of earned income, less KSh 5,000 of drawings, gives equity of KSh 130,000. The resources are cash KSh 80,000, laptop KSh 40,000 and inventory KSh 30,000. After accounting for the KSh 20,000 still owed, equity is again KSh 130,000. Two ways of checking reach the same answer. That agreement is more useful than memorising a rule without understanding it."},{"title":"Before you look at the answer","text":"A different business owns cash of KSh 70,000, equipment of KSh 40,000 and stock of KSh 20,000; it owes suppliers KSh 25,000. Work out total assets and equity before opening Practice. Your figures should be KSh 130,000 in assets and KSh 105,000 in equity. Try saying aloud why the supplier balance is deducted."}],"kenya_context_tab":[{"title":"A supplier's credit is not free income","text":"When a Kenyan supplier delivers goods on agreed credit terms, the purchasing business may have stock before it has paid. Its resources increase, but so does the amount it owes. A rising stock value is not evidence of higher profit by itself."},{"title":"Cash payment versus credit purchase","text":"Paying KSh 20,000 for equipment from existing bank funds changes the mix of assets. Buying the same equipment on credit creates both an asset and an obligation. The equipment can be identical while the accounting effects differ."}],"common_errors_tab":[{"title":"Both sides do not always increase","text":"A cash purchase exchanges assets. A debt repayment reduces an asset and a liability. A cash service fee can increase assets and equity. Work from the facts rather than using a single rule for every transaction."},{"title":"A balancing equation does not prove every entry is correct","text":"An incorrect classification can still leave both sides equal. The equation is a valuable cross-check, not a substitute for documentary evidence, recognition rules and careful review."},{"title":"Treating drawings as wages","text":"An owner's personal withdrawal is a transaction with the owner. Do not describe it as a wage paid to an employee or as ordinary trading expense."}],"clinical_tip_tab":[{"title":"Practise the movement, not just the final number","text":"For each new transaction, write the before-and-after figures for assets, liabilities and equity. Explain in one sentence why each category moved. If the equation fails, revisit the event rather than forcing the closing number to balance."}]}],"questions":[{"topic_slug":"why-accounts-matter","question_text":"Two firms each have KSh 100,000 in the bank. One owes suppliers KSh 90,000; the other owes nothing. What is the soundest conclusion?","options":[{"id":"a","label":"A","text":"They must have the same financial position."},{"id":"b","label":"B","text":"The first firm must have made a loss."},{"id":"c","label":"C","text":"Cash alone is insufficient to compare their financial positions."},{"id":"d","label":"D","text":"The second firm has no expenses."}],"correct_option_id":"c","explanation":"Equal cash balances do not tell us the value of other assets and obligations. We need the wider financial position before judging either business."},{"topic_slug":"why-accounts-matter","question_text":"Which statement best describes the purpose of financial accounting?","options":[{"id":"a","label":"A","text":"It guarantees that a business makes profit."},{"id":"b","label":"B","text":"It records and communicates financial information useful for decisions."},{"id":"c","label":"C","text":"It replaces the need for source documents."},{"id":"d","label":"D","text":"It reports only money in the bank."}],"correct_option_id":"b","explanation":"Financial accounting records and organises evidence of transactions into useful financial information. It does not guarantee profit."},{"topic_slug":"why-accounts-matter","question_text":"A bank is considering a loan to a business. Which information is most relevant?","options":[{"id":"a","label":"A","text":"Only the owner's preferred borrowing amount."},{"id":"b","label":"B","text":"Only the number of products sold."},{"id":"c","label":"C","text":"Only the business's name."},{"id":"d","label":"D","text":"Its obligations, resources and ability to generate cash."}],"correct_option_id":"d","explanation":"A lender needs evidence about financial position and prospects for repayment, not a single headline number."},{"topic_slug":"why-accounts-matter","question_text":"A sole trader transfers KSh 6,000 from the business account for personal groceries. How should the event ordinarily be described?","options":[{"id":"a","label":"A","text":"A drawing by the owner."},{"id":"b","label":"B","text":"Sales revenue."},{"id":"c","label":"C","text":"A trade receivable."},{"id":"d","label":"D","text":"A supplier discount."}],"correct_option_id":"a","explanation":"Personal withdrawals by a sole trader are drawings. They reduce the owner's interest in the business, not operating profit."},{"topic_slug":"five-elements-of-financial-statements","question_text":"A customer owes a business KSh 14,000 for an invoiced sale. Which element does the amount normally represent?","options":[{"id":"a","label":"A","text":"Expense."},{"id":"b","label":"B","text":"Trade receivable (asset)."},{"id":"c","label":"C","text":"Owner drawings."},{"id":"d","label":"D","text":"Trade payable (liability)."}],"correct_option_id":"b","explanation":"The business has a right to receive payment. Subject to appropriate recognition, that receivable is an asset rather than cash already received."},{"topic_slug":"five-elements-of-financial-statements","question_text":"A trader has KSh 65,000 bank, KSh 14,000 receivables and KSh 21,000 equipment. Suppliers are owed KSh 25,000 and an electricity bill of KSh 5,000 is outstanding. What is residual equity?","options":[{"id":"a","label":"A","text":"KSh 65,000."},{"id":"b","label":"B","text":"KSh 95,000."},{"id":"c","label":"C","text":"KSh 70,000."},{"id":"d","label":"D","text":"KSh 130,000."}],"correct_option_id":"c","explanation":"Assets: 65,000 + 14,000 + 21,000 = 100,000. Liabilities: 25,000 + 5,000 = 30,000. Equity: 100,000 − 30,000 = KSh 70,000."},{"topic_slug":"five-elements-of-financial-statements","question_text":"Which event by itself creates a present liability?","options":[{"id":"a","label":"A","text":"Thinking about buying stock next year."},{"id":"b","label":"B","text":"Drafting a budget for marketing."},{"id":"c","label":"C","text":"Deciding to save for equipment."},{"id":"d","label":"D","text":"Receiving goods under an agreement to pay the supplier next month."}],"correct_option_id":"d","explanation":"Receiving the goods on credit ordinarily creates a payable. A future plan or budget does not automatically create a present obligation."},{"topic_slug":"five-elements-of-financial-statements","question_text":"Which transaction ordinarily increases equity through income rather than owner contribution?","options":[{"id":"a","label":"A","text":"An owner deposits KSh 20,000 capital."},{"id":"b","label":"B","text":"A completed service earns KSh 20,000 cash."},{"id":"c","label":"C","text":"A bank lends KSh 20,000."},{"id":"d","label":"D","text":"The owner moves KSh 20,000 between personal savings accounts."}],"correct_option_id":"b","explanation":"Fees earned for a completed service increase income and normally equity. Capital contributions and loans are not revenue."},{"topic_slug":"the-equation-in-action","question_text":"A business has assets of KSh 180,000 and liabilities of KSh 65,000. What is its equity?","options":[{"id":"a","label":"A","text":"KSh 245,000."},{"id":"b","label":"B","text":"KSh 115,000."},{"id":"c","label":"C","text":"KSh 65,000."},{"id":"d","label":"D","text":"KSh 180,000."}],"correct_option_id":"b","explanation":"Equity = Assets − Liabilities = 180,000 − 65,000 = KSh 115,000."},{"topic_slug":"the-equation-in-action","question_text":"A business buys a KSh 20,000 computer using existing bank funds. What happens immediately in this simplified example?","options":[{"id":"a","label":"A","text":"Total assets increase by KSh 20,000."},{"id":"b","label":"B","text":"Equity falls by KSh 20,000."},{"id":"c","label":"C","text":"One asset falls while another rises; total assets do not change."},{"id":"d","label":"D","text":"A liability of KSh 20,000 is created."}],"correct_option_id":"c","explanation":"Bank cash falls by 20,000 and equipment rises by 20,000. The transaction exchanges one asset for another."},{"topic_slug":"the-equation-in-action","question_text":"Inventory costing KSh 25,000 is bought on supplier credit. What is the immediate effect?","options":[{"id":"a","label":"A","text":"Assets increase KSh 25,000 and liabilities increase KSh 25,000."},{"id":"b","label":"B","text":"Assets fall KSh 25,000 and liabilities increase KSh 25,000."},{"id":"c","label":"C","text":"Equity increases KSh 25,000 as profit."},{"id":"d","label":"D","text":"Cash falls KSh 25,000."}],"correct_option_id":"a","explanation":"Inventory increases by KSh 25,000 and a trade payable of the same amount arises. Cash has not yet been paid."},{"topic_slug":"the-equation-in-action","question_text":"After six transactions a business has cash KSh 80,000, laptop KSh 40,000 and inventory KSh 30,000. It owes suppliers KSh 20,000. What is its equity?","options":[{"id":"a","label":"A","text":"KSh 170,000."},{"id":"b","label":"B","text":"KSh 20,000."},{"id":"c","label":"C","text":"KSh 110,000."},{"id":"d","label":"D","text":"KSh 130,000."}],"correct_option_id":"d","explanation":"Assets = 80,000 + 40,000 + 30,000 = KSh 150,000. Equity = 150,000 − 20,000 = KSh 130,000."}]}$ca11data$::jsonb as data
), target as (
 select m.id as module_id from public.modules m
 join public.courses c on c.id=m.course_id
 where c.slug='kasneb-cpa' and m.slug='ca11'
), authored as (
 select t.*, target.module_id from packet, target,
 jsonb_to_recordset(packet.data->'topics') as t(
  slug text,title text,subtitle text,sequence_number integer,
  concept_tab jsonb,kenya_context_tab jsonb,common_errors_tab jsonb,clinical_tip_tab jsonb)
)
insert into public.topics
 (module_id,slug,title,subtitle,sequence_number,week_number,concept_tab,kenya_context_tab,common_errors_tab,clinical_tip_tab,content_status)
select module_id,slug,title,subtitle,sequence_number,null,concept_tab,kenya_context_tab,common_errors_tab,clinical_tip_tab,'in_review'
from authored
on conflict (module_id,slug) do nothing;

